void Solver::rephase() {
    // Adaptive rephasing based on solver state
    if (rephases == 0) {
        // First rephase: aggressive reset
        threshold *= 0.7;
        rephase_limit += 4096;
    } else {
        // Subsequent rephases: more conservative
        threshold *= 0.95;
        rephase_limit += 2048;
    }

    // Update saved phases based on current trail
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Reinforce current assignment with some randomness
            saved[i] = (rand() % 100 < 80) ? value[i] : -value[i];
        } else if (saved[i] == 0) {
            // Initialize unassigned variables randomly
            saved[i] = (rand() % 2) ? 1 : -1;
        }
    }

    rephases++;
}
